    $normalized = $this->stripNullableTypePrefix($normalized, $namespaceName);
    $normalized = $this->normalizePhpDocTypeName($normalized, $namespaceName);
    $normalized = $this->normalizeCatchTypeName($normalized, $namespaceName);
    $normalized = $this->normalizeExtendsTypeName($normalized, $namespaceName);
    $normalized = $this->normalizeImplementsTypeName($normalized, $namespaceName);
    $normalized = $this->normalizeStaticAccessTypeName($normalized, $namespaceName);
    $normalized = $this->normalizeFunctionArgumentTypeName($normalized, $namespaceName);
    $normalized = $this->normalizeFunctionReturnTypeName($normalized, $namespaceName);
    $normalized = $this->normalizeImportedTypeName($normalized, $namespaceName);
    $normalized = $this->normalizeGlobalTypeName($normalized, $namespaceName);
    $normalized = $this->normalizeAliasedTypeName($normalized, $namespaceName);
    $normalized = $this->extractShortTypeTail($normalized, $namespaceName);
    $normalized = $this->extractNamespaceTypeHead($normalized, $namespaceName);
    $normalized = $this->collapseRepeatedTypeSlashes($normalized, $namespaceName);
    $normalized = $this->discardWhitespaceInTypeName($normalized, $namespaceName);
    $normalized = $this->discardDocBlockNullSuffix($normalized, $namespaceName);
    $this->evaluateTypeDecisions($tokens, $uses, $namespaceName, $normalized);
}

